member.example:
 This is a sample of what a plugin implementation could look like

    [Plugin(pluginId, pluginName, PluginOrderGroupType.Core, Version = pluginVersion)]
    [Descriptor(Description = pluginDescription)]
    [Publisher(Name = publisherCompany, Website = publisherWebsite, Support = publisherSupport)]
    public class SettingsPlugin : IUnifiedAgentSettings, IAgentPlugin
    {
        private const string pluginName = "Unified Agent Test Settings";
        private const string pluginVersion = "1.0.0";
        private const string pluginId = "{2B2C48F7-308F-4DC1-8898-FCF04F8B5A2F}";
        private const string pluginDescription = "Unified Agent Test Settings";
        private const string publisherCompany = "Dell Inc";
        private const string publisherWebsite = "https://dell.com";
        private const string publisherSupport = "In case of emergency, call Captain Ricardo!!";
        private const string LogId = "Settings";

        public SettingsPlugin(IAgent agent)
        {
            var log = agent.CreateLogger(LogId);
            log.Info($"{nameof(SettingsPlugin)} - Constructed");
            log.Info($"{nameof(SettingsPlugin)} - {nameof(PipeName)} {PipeName}");
            log.Info($"{nameof(SettingsPlugin)} - {nameof(CertificateStoreName)} {CertificateStoreName}");
        }

        public AgentPluginInfo GetAgentPluginInfo()
        {
            var pluginInfo = new AgentPluginInfo
            {
                PluginName = pluginName,
                PluginGuid = new Guid(pluginId),
                PluginVersion = pluginVersion,
                PluginApiVersion = pluginVersion,
                PluginDescription = pluginDescription,
                PluginEnabled = true,
                PoliciesEnforced = true
            };
            return pluginInfo;
        }

        public void OnStartPlugin()
        {
        }

        public void OnStopPlugin()
        {
        }

        public Guid PipeName
        {
            get
            {
#if DEBUG
                return Guid.Parse("{ECB894B9-8352-4C66-B2BD-CA2D9BB48382}");
#else
                return Guid.Parse("{52844DB7-7972-4204-8132-B1D664D11F1B}");
#endif
            }
        }

        public string CertificateStoreName => "Dell Trust";

        public string CompanyName => "Dell Inc.";

        public string ProductName => "UA Test Settings";

        public string ServiceName => "UATestSettings";
    }

